<script setup lang="ts">
import ConsoleDrawer from '../console/ConsoleDrawer.vue'
import ConsoleDiscardChangesDialog from '../console/ConsoleDiscardChangesDialog.vue'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import MaterialPicker from '../console/MaterialPicker.vue'
import ImageSelectTile from '../console/ImageSelectTile.vue'
const props=defineProps<{tenantId:string;applicationKey:string;page:'home'|'profile'}>()
const open=defineModel<boolean>('open',{default:false})
type Config={title:string;imageId:string|null;description?:string}
type View={canWrite:boolean;channels:Record<'mini'|'official',{version:number;config:Config}>}
const toast=useToast(),auth=useApi('tenant'),channel=ref<'mini'|'official'>('mini'),data=ref<View|null>(null),forms=ref<Record<'mini'|'official',Config>>({mini:{title:'',imageId:null},official:{title:'',imageId:null,description:''}}),baseline=ref(''),busy=ref(''),error=ref(''),picker=ref(false)
const endpoint=computed(()=>'/admin/tenants/'+encodeURIComponent(props.tenantId)+'/page-sharing/'+encodeURIComponent(props.applicationKey)+'/'+props.page),dirty=computed(()=>!!data.value&&JSON.stringify(forms.value)!==baseline.value),locked=computed(()=>!!busy.value||!data.value?.canWrite),discard=useDiscardChanges(()=>!!busy.value)
let controller=new AbortController(),attempt=0,disposed=false
async function load(){const n=++attempt;controller.abort();controller=new AbortController();data.value=null;error.value='';busy.value='load';try{const value=await auth.api<View>(endpoint.value,'GET',undefined,{signal:controller.signal});if(disposed||n!==attempt)return;data.value=value;forms.value={mini:JSON.parse(JSON.stringify(value.channels.mini.config)),official:JSON.parse(JSON.stringify(value.channels.official.config))};baseline.value=JSON.stringify(forms.value)}catch(e:any){if(!disposed&&n===attempt)error.value=e.message}finally{if(!disposed&&n===attempt)busy.value=''}}
watch(()=>[open.value,props.page,props.applicationKey],()=>{if(open.value)void load()},{immediate:true})
function close(){if(busy.value)return;if(dirty.value){discard.request(()=>{open.value=false;discard.keep()});return}open.value=false}
async function save(){if(locked.value||!data.value)return;const current=channel.value;busy.value='save:'+current;error.value='';const snapshot=JSON.parse(JSON.stringify(forms.value[current]));try{const result=await auth.api<View>(endpoint.value+'/'+current,'PUT',{version:data.value.channels[current].version,config:snapshot},{signal:controller.signal});if(disposed)return;data.value=result;forms.value[current]=JSON.parse(JSON.stringify(result.channels[current].config));const saved=JSON.parse(baseline.value);saved[current]=forms.value[current];baseline.value=JSON.stringify(saved);toast.add({title:'分享设置已保存',color:'success'})}catch(e:any){if(!disposed)error.value=e.message}finally{if(!disposed)busy.value=''}}
function imageUrl(id:string){return '/api/v1/admin/tenants/'+encodeURIComponent(props.tenantId)+'/materials/'+encodeURIComponent(props.applicationKey)+'/'+encodeURIComponent(id)+'/content?purpose=library'}
onBeforeRouteLeave(to=>{if(busy.value)return false;if(dirty.value){discard.request(()=>{baseline.value=JSON.stringify(forms.value);open.value=false;void navigateTo(to.fullPath)});return false}})
onBeforeUnmount(()=>{disposed=true;attempt++;controller.abort()})
</script>
<template><ConsoleDrawer :open="open" title="分享设置" :description="page==='home'?'首页':'个人中心'" :dismissible="!busy" :close="!busy" @update:open="!$event&&close()"><template #body><div class="share-tabs"><button type="button" :class="{active:channel==='mini'}" :disabled="!!busy" @click="channel='mini'">微信小程序</button><button type="button" :class="{active:channel==='official'}" :disabled="!!busy" @click="channel='official'">微信公众号</button></div><UAlert v-if="error" color="error" :title="error" class="mb-5"><template v-if="!data" #actions><UButton :loading="busy==='load'" @click="load">重试</UButton></template></UAlert><div v-if="busy==='load'" class="py-16 text-center text-muted text-sm">正在读取分享设置…</div><form v-else-if="data" id="page-sharing-form" class="space-y-6" @submit.prevent="save"><ConsoleSettingsField label="分享页面"><p class="text-sm">{{page==='home'?'首页':'个人中心'}}</p></ConsoleSettingsField><ConsoleSettingsField label="分享标题"><ConsoleInput v-model="forms[channel].title" :maxlength="30" :disabled="locked" placeholder="留空使用页面标题"/><p class="mt-2 text-xs text-muted">{{forms[channel].title.length}} / 30</p></ConsoleSettingsField><ConsoleSettingsField v-if="channel==='official'" label="分享描述"><textarea v-model="forms.official.description" rows="4" maxlength="100" :disabled="locked" class="share-description" placeholder="分享时展示的简短介绍"/><p class="mt-2 text-xs text-muted">{{forms.official.description?.length||0}} / 100</p></ConsoleSettingsField><ConsoleSettingsField label="分享图片"><ImageSelectTile :src="forms[channel].imageId?imageUrl(forms[channel].imageId!):null" label="分享图片" fit="contain" :disabled="locked" :removable="!!forms[channel].imageId" @select="picker=true" @remove="forms[channel].imageId=null"/><p class="mt-3 text-xs leading-6 text-muted">分享图片供访客和微信读取，请使用可公开的图片。留空时由客户端使用默认分享画面。</p></ConsoleSettingsField></form><MaterialPicker v-model:open="picker" portal="tenant" purpose="library" kind="image" :endpoint="'/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(applicationKey)" @select="forms[channel].imageId=$event.id"/><ConsoleDiscardChangesDialog :controller="discard"/></template><template #footer><ConsoleFormActions><span v-if="dirty" class="mr-auto text-xs text-muted">有未保存的修改</span><UButton color="neutral" variant="outline" :disabled="!!busy" @click="close">关闭</UButton><UButton type="submit" form="page-sharing-form" :disabled="locked" :loading="busy==='save:'+channel">保存{{channel==='mini'?'小程序':'公众号'}}设置</UButton></ConsoleFormActions></template></ConsoleDrawer></template>
<style scoped>.share-tabs{display:flex;gap:22px;border-bottom:1px solid var(--ui-border);margin-bottom:24px}.share-tabs button{padding:0 0 13px;font-size:13px;color:var(--ui-text-muted)}.share-tabs button.active{color:var(--ui-primary);box-shadow:0 2px var(--ui-primary)}.share-description{width:100%;border:1px solid var(--ui-border);border-radius:7px;padding:9px 11px;resize:vertical;background:var(--ui-bg);font-size:13px;line-height:1.7}</style>
